import json,importlib.util,socket,os,pathlib
out={'telethon_installed':importlib.util.find_spec('telethon') is not None,'api_id_configured':False,'tgws_config_keys':[],'tgws_secret_shape':'not_found','tgws_listening':False}
p=pathlib.Path(os.environ.get('APPDATA',''))/'TgWsProxy'/'config.json'
try:
 c=json.loads(p.read_text(encoding='utf-8-sig'))
 out['tgws_config_keys']=sorted(list(c.keys()))
 for k,v in c.items():
  if 'secret' in k.lower():
   out['tgws_secret_shape']='type_'+type(v).__name__+'_length_'+str(len(v)) if isinstance(v,str) else type(v).__name__
except Exception as e:out['config_error']=type(e).__name__
try:
 s=socket.create_connection(('127.0.0.1',1443),timeout=1.5)
 s.close();out['tgws_listening']=True
except Exception as e:out['tgws_check_error']=type(e).__name__
print(json.dumps(out,ensure_ascii=True))
